assert p.count(old_validate) == 1, 'promotion validation anchor mismatch'
p = p.replace(old_validate, new_validate, 1)

old_start = """          source_sql=\"select (select count(*) from cron.job) cron_jobs,(select count(*) from pg_publication where pubname='${FORWARD_PUBLICATION}') publication_count,(select count(*) from pg_replication_slots where slot_name='${FORWARD_SLOT}') slot_count,(select count(*) from pg_replication_slots where slot_name='${FORWARD_SLOT}' and active) active_slots;\"\n          target_sql=\"select (select count(*) from cron.job where active) active_cron_jobs,(select count(*) from pg_subscription where subname='${FORWARD_SUBSCRIPTION}' and subenabled) enabled_subscriptions,(select count(*) from pg_stat_subscription where subname='${FORWARD_SUBSCRIPTION}' and pid is not null) workers,(select count(*) from pg_subscription_rel sr join pg_subscription s on s.oid=sr.srsubid where s.subname='${FORWARD_SUBSCRIPTION}' and sr.srsubstate='r') ready_tables;\"\n          query_ref \"$VIRGINIA_REF\" \"$source_sql\" \"$RUNNER_TEMP/source-start.json\"\n          query_ref \"$OREGON_REF\" \"$target_sql\" \"$RUNNER_TEMP/target-start.json\"\n          jq -e '.[0].cron_jobs==0 and .[0].publication_count==1 and .[0].slot_count==1 and .[0].active_slots==1' \"$RUNNER_TEMP/source-start.json\" >/dev/null\n          jq -e '.[0].active_cron_jobs==0 and .[0].enabled_subscriptions==1 and .[0].workers==1 and .[0].ready_tables==462' \"$RUNNER_TEMP/target-start.json\" >/dev/null\n"""
