p = p.replace(old_start, new_start, 1)

old_fence = """          query_ref \"alter role postgres set default_transaction_read_only=off; alter database postgres set default_transaction_read_only=on;\" \"$RUNNER_TEMP/fence-set.json\"\n          query_ref \"select pg_terminate_backend(pid) terminated from pg_stat_activity where pid<>pg_backend_pid() and usename in ('authenticator','supabase_auth_admin','supabase_storage_admin');\" \"$RUNNER_TEMP/fence-terminate.json\"\n          query_ref \"select (select count(*) from pg_db_role_setting s join pg_database d on d.oid=s.setdatabase where d.datname='postgres' and s.setrole=0 and coalesce(array_to_string(s.setconfig,','),'') like '%default_transaction_read_only=on%') database_fences,(select count(*) from pg_roles where rolname='postgres' and coalesce(array_to_string(rolconfig,','),'') like '%default_transaction_read_only=off%') admin_overrides,(select count(*) from pg_roles where rolname in ('authenticator','supabase_auth_admin','supabase_storage_admin') and coalesce(array_to_string(rolconfig,','),'') like '%default_transaction_read_only=off%') service_write_overrides;\" \"$RUNNER_TEMP/fence-verify.json\"\n          jq -e '.[0].database_fences==1 and .[0].admin_overrides==1 and .[0].service_write_overrides==0' \"$RUNNER_TEMP/fence-verify.json\" >/dev/null || { echo 'Virginia database write fence did not apply.' >&2; exit 1; }\n          printf '%s' true > \"$RUNNER_TEMP/virginia-fenced\"\n"""
new_fence = """          query_ref \"alter role postgres set default_transaction_read_only=off; alter database postgres set default_transaction_read_only=on; alter database postgres set \\\"theouthaven.dr_write_fence\\\"=on;\" \"$RUNNER_TEMP/fence-set.json\"\n          query_ref \"select pg_terminate_backend(pid) terminated from pg_stat_activity where pid<>pg_backend_pid() and usename in ('authenticator','supabase_auth_admin','supabase_storage_admin');\" \"$RUNNER_TEMP/fence-terminate.json\"\n          query_ref \"select (select count(*) from pg_db_role_setting s join pg_database d on d.oid=s.setdatabase where d.datname='postgres' and s.setrole=0 and coalesce(array_to_string(s.setconfig,','),'') like '%default_transaction_read_only=on%') database_fences,(select count(*) from pg_db_role_setting s join pg_database d on d.oid=s.setdatabase where d.datname='postgres' and s.setrole=0 and coalesce(array_to_string(s.setconfig,','),'') like '%theouthaven.dr_write_fence=on%') api_fences,(select count(*) from pg_roles where rolname='postgres' and coalesce(array_to_string(rolconfig,','),'') like '%default_transaction_read_only=off%') admin_overrides,(select count(*) from pg_roles where rolname in ('authenticator','supabase_auth_admin','supabase_storage_admin') and coalesce(array_to_string(rolconfig,','),'') like '%default_transaction_read_only=off%') service_write_overrides,(select count(*) from pg_roles where rolname='authenticator' and coalesce(array_to_string(rolconfig,','),'') like '%pgrst.db_pre_request=public.theouthaven_dr_pre_request%') dr_pre_request_configured;\" \"$RUNNER_TEMP/fence-verify.json\"\n          jq -e '.[0].database_fences==1 and .[0].api_fences==1 and .[0].admin_overrides==1 and .[0].service_write_overrides==0 and .[0].dr_pre_request_configured==1' \"$RUNNER_TEMP/fence-verify.json\" >/dev/null || { echo 'Virginia layered write fence did not apply.' >&2; exit 1; }\n          printf '%s' true > \"$RUNNER_TEMP/virginia-fenced\"\n"""
